using Test, StatsBase
import PIC, TwoDimensional, OptimPackNextGen

numlens = 8725

lens_dx_lower = PIC.LENS_DX_LOWER
lens_dx_upper = PIC.LENS_DX_UPPER
lens_dy_lower = PIC.LENS_DY_LOWER
lens_dy_upper = PIC.LENS_DY_UPPER

lens_width  = lens_dx_lower + 1 + lens_dx_upper
lens_height = lens_dy_lower + 1 + lens_dy_upper

bbox = round(Int, TwoDimensional.BoundingBox(
    (disp_cxy0s[numlens,1] - lens_dx_lower), (disp_cxy0s[numlens,1] + lens_dx_upper),
    (disp_cxy0s[numlens,2] - lens_dy_lower), (disp_cxy0s[numlens,2] + lens_dy_upper)),
    RoundNearestTiesUp)

@test size(bbox) == (lens_width, lens_height)

# we will not use full data matrix in this test script to save some space,
# we only use the data for the given lenslet,
# so we redefine bbox
lens_bbox = TwoDimensional.BoundingBox{Int64}(; xmin=1, xmax=lens_width, ymin=1, ymax=lens_height)

