lens_lamp_weights = lens_good_pixels

nλ = 3
lasers_λs = PIC.LASERS_λS[1:nλ]
lasers_fwhms_init = PIC.LASERS_FWHMS_INIT[1:nλ]
λref = mean(lasers_λs)
profile_order = 2

lens_model = PIC.LensletModel(lens_bbox, λref, PIC.DISP_ORDER, profile_order)

@test lens_model.disp_model.λref == λref
@test lens_model.disp_model.order == PIC.DISP_ORDER
@test length(lens_model.disp_model.cx) == PIC.DISP_ORDER + 1
@test length(lens_model.disp_model.cy) == PIC.DISP_ORDER + 1
@test lens_model.disp_model.cx[1] == 1
@test lens_model.disp_model.cy[1] == 1
@test iszero(sum(lens_model.disp_model.cx[2:end]))
@test iszero(sum(lens_model.disp_model.cy[2:end]))

disp_cxy0s = PIC.DISPERSION_CXY0S
fitvars = [ lasers_fwhms_init...                     ;
            disp_cxy0s[numlens,1:2]...               ;
            PIC.DISPERSION_CX1_MEDIAN * (λref*1e6)   ;
            PIC.DISPERSION_CY1_MEDIAN * (λref*1e6)   ;
            PIC.DISPERSION_CX2_MEDIAN * (λref*1e6)^2 ;
            PIC.DISPERSION_CY2_MEDIAN * (λref*1e6)^2 ]
disp_lkl = PIC.Dispersion_LKL(lens_bbox, lens_model.disp_model,
                              lasers_λs, lens_lasers_data, lens_lasers_weights)

@test disp_lkl.nλ == nλ
@test length(disp_lkl.amplitude) == nλ
@test iszero(sum(disp_lkl.amplitude))
@test disp_lkl.bbox == lens_bbox
@test disp_lkl.data == lens_lasers_data
@test disp_lkl.weights == lens_lasers_weights
@test size(disp_lkl.spots) == (size(lens_bbox)..., nλ)
@test iszero(sum(disp_lkl.spots))

OptimPackNextGen.vmlmb!(disp_lkl, fitvars; verb=true, ftol=(0.0,1e-8), maxeval=500, autodiff=true)

